import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BWixA7XM.js";const p=JSON.parse('{"title":"这套教程讲什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1795572648000}'),o={name:"guide/index.md"};function i(l,t,n,s,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="这套教程讲什么" tabindex="-1">这套教程讲什么 <a class="header-anchor" href="#这套教程讲什么" aria-label="Permalink to &quot;这套教程讲什么&quot;">​</a></h1><p>先明确边界：<strong>这套教程不假设你装了 SSMT4，也不假设你装了任何 Mod 工具。</strong></p><p>只用：</p><ul><li>一个 3DMigoto 的 FrameAnalysis 转储目录</li><li>Python + numpy</li><li>一个文本编辑器</li><li>Blender</li></ul><p>目标是把转储里「某个 IB」对应的模型，还原成一个能编辑的网格，并且<strong>这个网格改完之后还能写回游戏</strong>。</p><h2 id="为什么不用工具" tabindex="-1">为什么不用工具 <a class="header-anchor" href="#为什么不用工具" aria-label="Permalink to &quot;为什么不用工具&quot;">​</a></h2><p>用 SSMT4 这类工具当然更快 —— 点几下就出结果。但你会卡在三个地方：</p><ol><li><strong>工具不支持你的游戏</strong>。SSMT4 每个游戏都要写一份 extractor，新游戏出来之前没有。</li><li><strong>工具报错你不知道为什么</strong>。看着「无法识别数据类型」的提示，只能去问作者。</li><li><strong>数据类型选错了不会自救</strong>。工具给了你几个候选，你不清楚差别在哪，选完发现模型缺了半身。</li></ol><p>读完这套教程，这三件事你都能自己处理。</p><h2 id="教程怎么组织的" tabindex="-1">教程怎么组织的 <a class="header-anchor" href="#教程怎么组织的" aria-label="Permalink to &quot;教程怎么组织的&quot;">​</a></h2><p>五个步骤，每步都能独立验证：</p><table tabindex="0"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>怎么验证对了</th></tr></thead><tbody><tr><td><a href="/SSMT4-Tutorial/guide/dump/find-ib">锁定目标 IB</a></td><td>转储目录</td><td>一个 8 位哈希 + 它的 draw 列表</td><td>索引数量、贴图反查</td></tr><tr><td><a href="/SSMT4-Tutorial/guide/gametype/what-is-gametype">搞懂数据类型</a></td><td>VB 的 <code>.txt</code> header</td><td>每顶点 stride 的字段拆分表</td><td><code>.txt</code> 末尾的 <code>vertex-data</code> 预览值</td></tr><tr><td><a href="/SSMT4-Tutorial/guide/extract/vertices">切顶点与索引</a></td><td><code>.buf</code> + 字段表</td><td>顶点数组 + 三角形数组</td><td>跨缓冲顶点数一致、索引不越界</td></tr><tr><td><a href="/SSMT4-Tutorial/guide/blender/obj">坐标与朝向</a></td><td>顶点数组</td><td>轴对、绕序对、UV 对的网格</td><td>法线点积、人形轮廓、贴图采样</td></tr><tr><td><a href="/SSMT4-Tutorial/guide/mod/writeback">做回 Mod</a></td><td>改完的网格</td><td>能写回的原字节</td><td>重建整条缓冲逐字节比对</td></tr></tbody></table><p>每一步都给出<strong>明确的通过标准</strong>。达不到就不要往下走 —— 后面只会更乱。</p><h2 id="一个贯穿全文的例子" tabindex="-1">一个贯穿全文的例子 <a class="header-anchor" href="#一个贯穿全文的例子" aria-label="Permalink to &quot;一个贯穿全文的例子&quot;">​</a></h2><p>教程用一个真实案例展开：<a href="/SSMT4-Tutorial/case/7ad7e69e">IB <code>7ad7e69e</code></a>，一个 24068 顶点、29606 三角形的角色模型，带 141 根骨骼。</p><p>选它是因为它把坑都踩全了：</p><ul><li>同一个模型在转储里<strong>有两份顶点缓冲</strong>：一份 T-pose（绑定姿势），一份已蒙皮（当前动画姿势）。取错了模型就会摆着一个踢腿姿势。</li><li>4 段 IB 被 16 个 draw 引用，分成 4 套不同的输入布局。</li><li>顶点色 B 通道 100% 恒等于 128，看着像垃圾数据，其实是着色参数。</li><li>UV 的 V 轴要不要翻转，靠算法判不出来，得看贴图。</li></ul><h2 id="用词约定" tabindex="-1">用词约定 <a class="header-anchor" href="#用词约定" aria-label="Permalink to &quot;用词约定&quot;">​</a></h2><ul><li><strong>「转储」= FrameAnalysis 目录</strong>，就是按 F8 生成的那一堆 <code>.buf</code> / <code>.txt</code> / <code>.lnk</code></li><li><strong>「IB」= Index Buffer</strong>，8 位十六进制哈希指代它，例如 <code>7ad7e69e</code></li><li><strong>「draw」= drawcall</strong>，6 位十进制序号指代它，例如 <code>000081</code></li><li><strong>「数据类型」= GameType</strong>，一套字段拆分方案的名字，例如 <code>CPU_P12_N12_TA16_C4_T8_</code></li></ul><p>完整定义见<a href="/SSMT4-Tutorial/dev/glossary">术语表</a>。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>需要的：</p><ul><li>Python 基础语法（会写 <code>for</code> 循环和函数就行）</li><li>numpy 的 <code>frombuffer</code> / <code>dtype</code> 概念（教程里会讲，但见过会更快）</li><li>一个 3D 软件的基本操作（导模型、看 UV、看顶点组）</li></ul><p>不需要的：</p><ul><li>dx11 编程经验（教程会解释用到的每一个 API）</li><li>图形学数学（叉积、点积这一级别，用到时会说清）</li><li>汇编 / 逆向经验</li></ul><h2 id="免责声明" tabindex="-1">免责声明 <a class="header-anchor" href="#免责声明" aria-label="Permalink to &quot;免责声明&quot;">​</a></h2><p>改模型这件事本身在多数游戏的服务条款里是受限的。这套教程的内容面向<strong>单机模型研究与个人练习</strong>。分发修改后的资源、在联机环境使用，风险自负。</p>',27)])])}const g=e(o,[["render",i]]);export{p as __pageData,g as default};
